import { test, expect } from '../../../fixtures';

test('TC-063: Inactive product detail reported 404 for non-admin viewer', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  // reset_state step: satisfied by the automatic per-test reset
  await loginAs('standard_user');  // customer-session variation
  await loginAs('admin');  // include_inactive listing resolves the inactive id
  const allProducts: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products?include_inactive=true')).json();
  const inactiveProduct = allProducts.find((p) => p.is_active === false);
  if (!inactiveProduct) throw new Error('seed has no inactive product');
  await loginAs('standard_user');  // switch to a non-admin session for the check itself
  const res = await api.get(`/api/products/${inactiveProduct.id}`);
  expect(res.status()).toBe(404);
  // Expected (full): 404 Not Found; body indicates not found; no inactive data leaked
});
